namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0
        ? Math.Round((double)RatingSum / TotalRatings, 1)
        : 0;
}

namespace RecipeCommunity.Models;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Spaghetti Carbonara", Category = "Pasta",
                Description = "Classic Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["400g spaghetti", "200g pancetta", "4 egg yolks", "100g Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk egg yolks with grated cheese and pepper.", "Drain pasta, toss with pancetta, then mix in egg mixture off heat.", "Serve immediately with extra cheese."],
                TotalRatings = 12, RatingSum = 53
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Curries",
                Description = "Tender chicken in a creamy spiced tomato sauce.",
                Ingredients = ["500g chicken breast", "200ml yogurt", "2 tbsp tikka paste", "400g canned tomatoes", "200ml cream", "1 onion", "Garlic and ginger"],
                Steps = ["Marinate chicken in yogurt and tikka paste for 1 hour.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger, then add tomatoes.", "Simmer sauce 15 minutes, stir in cream.", "Add chicken to sauce and simmer 10 more minutes."],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Caesar Salad", Category = "Salads",
                Description = "Crisp romaine with creamy Caesar dressing and croutons.",
                Ingredients = ["1 head romaine lettuce", "Caesar dressing", "Croutons", "Parmesan cheese", "Lemon juice"],
                Steps = ["Wash and chop romaine lettuce.", "Toss lettuce with Caesar dressing.", "Top with croutons and shaved Parmesan.", "Squeeze lemon juice on top and serve."],
                TotalRatings = 5, RatingSum = 21
            },
            new Recipe
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich chocolate cake with a molten center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour"],
                Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into greased ramekins and bake at 220°C for 12 minutes.", "Invert onto plates and serve immediately."],
                TotalRatings = 15, RatingSum = 72
            },
            new Recipe
            {
                Id = 5, Title = "Mushroom Risotto", Category = "Pasta",
                Description = "Creamy Italian rice dish with earthy mushrooms.",
                Ingredients = ["300g arborio rice", "250g mixed mushrooms", "1L vegetable stock", "1 onion", "100ml white wine", "50g Parmesan", "Butter"],
                Steps = ["Sauté onion in butter, add sliced mushrooms.", "Add rice and toast for 2 minutes.", "Pour in wine and stir until absorbed.", "Add stock one ladle at a time, stirring constantly.", "Finish with Parmesan and a knob of butter."],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 6, Title = "Greek Salad", Category = "Salads",
                Description = "Fresh Mediterranean salad with feta and olives.",
                Ingredients = ["4 tomatoes", "1 cucumber", "1 red onion", "200g feta cheese", "Kalamata olives", "Olive oil", "Oregano"],
                Steps = ["Chop tomatoes, cucumber, and onion into chunks.", "Arrange on a plate with olives.", "Place a block of feta on top.", "Drizzle with olive oil and sprinkle oregano."],
                TotalRatings = 4, RatingSum = 17
            },
            new Recipe
            {
                Id = 7, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy taco shells.",
                Ingredients = ["500g ground beef", "Taco seasoning", "8 taco shells", "Lettuce", "Tomato", "Cheese", "Sour cream"],
                Steps = ["Brown ground beef and drain fat.", "Add taco seasoning with water, simmer 5 minutes.", "Warm taco shells in oven.", "Fill shells with beef and top with lettuce, tomato, cheese, and sour cream."],
                TotalRatings = 10, RatingSum = 43
            },
            new Recipe
            {
                Id = 8, Title = "Thai Green Curry", Category = "Curries",
                Description = "Fragrant coconut curry with vegetables and basil.",
                Ingredients = ["400ml coconut milk", "3 tbsp green curry paste", "300g chicken or tofu", "1 eggplant", "Thai basil", "Fish sauce", "Palm sugar"],
                Steps = ["Heat half the coconut milk and fry curry paste until fragrant.", "Add protein and cook through.", "Add remaining coconut milk, eggplant, fish sauce, and sugar.", "Simmer until eggplant is tender.", "Stir in Thai basil and serve with rice."],
                TotalRatings = 7, RatingSum = 32
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

